        .help = "usage: mopm package versions <namespace>/<name> [--cursor <cursor>] [--limit <n>] [--registry <prod|gamma|beta|url>] [--config-dir <dir>] [--json]\n\nList the versions of a package.\n\nIncludes yanked and tombstoned versions, with their state.\n\narguments:\n  <namespace>/<name>\n      The namespace of the package, a GitHub login in lower case.\n      Normalised package name, the part of the full name after the `/`.\noptions:\n  --cursor <cursor>\n      Opaque. Pass the `next_cursor` of the previous page.\n  --limit <n>\n  --registry <prod|gamma|beta|url>\n      the registry (default prod)\n  --config-dir <dir>\n      where 'mopm login' keeps credentials.json (default ~/.config/mopm)\n  --json\n      print the registry's answer as JSON instead of text\n\nSends GET /api/v2/packages/{namespace}/{name}/versions (listVersions).\n",
        .token = false,
        .body = .none,
        .args = &.{
            .{ .meta = "<namespace>/<name>", .key = "namespace/name", .full_name = true },
        },
        .flags = &.{
            .{ .flag = "--cursor", .meta = "<cursor>", .key = "cursor", .in = .params, .kind = .string },
            .{ .flag = "--limit", .meta = "<n>", .key = "limit", .in = .params, .kind = .integer },
        },
