    .{
        .name = "package version",
        .Op = v2.GetVersion,
        .summary = "Show one version of a package: its state, files and dependencies.",
        .usage = "usage: mopm package version <namespace>/<name> <version> [--registry <prod|gamma|beta|url>] [--config-dir <dir>] [--json]\n",
        .help = "usage: mopm package version <namespace>/<name> <version> [--registry <prod|gamma|beta|url>] [--config-dir <dir>] [--json]\n\nShow one version of a package: its state, files and dependencies.\n\nA yanked version is returned with `state: yanked` and its reason. A\ntombstoned version is returned with `state: tombstoned`, the reason\ncode and the sha256 of each file, but no `url`.\n\narguments:\n  <namespace>/<name>\n      The namespace of the package, a GitHub login in lower case.\n      Normalised package name, the part of the full name after the `/`.\n  <version>\noptions:\n  --registry <prod|gamma|beta|url>\n      the registry (default prod)\n  --config-dir <dir>\n      where 'mopm login' keeps credentials.json (default ~/.config/mopm)\n  --json\n      print the registry's answer as JSON instead of text\n\nSends GET /api/v2/packages/{namespace}/{name}/{version} (getVersion).\n",
